    /// Returns the account balance (USD), whether the account has made a deposit (required before
    /// posting jobs), AI task access status and the commission rate added to job costs.
    ///
    /// Tool `get_account`. Read-only: retried automatically after network and gateway errors.
    pub async fn get_account(&self) -> Result<Value> {
        self.call_tool("get_account", Value::Object(Map::new()))
            .await
    }

    /// Returns platform rules (minimum pay $0.05 per task, $0.10 for AI tasks, at least 10 workers
    /// per job, $20 minimum deposit, commission and fees), job categories with sub-category codes,
    /// the prefilled job types with the link each one expects, AI task types and the allowed ISO
    /// country codes. Call it before creating a job.
    ///
    /// Tool `get_platform_info`. Read-only: retried automatically after network and gateway errors.
    pub async fn get_platform_info(&self, params: GetPlatformInfoParams) -> Result<Value> {
        self.call_tool("get_platform_info", to_arguments(&params)?)
            .await
    }

    /// Returns the 20 most recent balance transactions (deposits, job charges, refunds).
    ///
    /// Tool `list_transactions`. Read-only: retried automatically after network and gateway errors.
    pub async fn list_transactions(&self) -> Result<Value> {
        self.call_tool("list_transactions", Value::Object(Map::new()))
            .await
    }

